mapper.select:
SELECT * FROM ( SELECT it.TRANSFER_ID, it.TRANSFER_NO, it.ITEM_ID, it.FROM_WH_ID, it.TO_WH_ID, it.QUANTITY, it.STATUS, it.REMARK, it.CREATED_AT, it.EMP_ID as empId, i.ITEM_CODE, i.ITEM_NAME, cc.CODE as itemUnit, fw.WH_NAME as fromWhName, tw.WH_NAME as toWhName, e.EMP_NAME, ROW_NUMBER() OVER (ORDER BY it.TRANSFER_ID DESC) as rnum FROM INVENTORY_TRANSFER it JOIN ITEM i ON it.ITEM_ID = i.ITEM_ID JOIN WAREHOUSE fw ON it.FROM_WH_ID = fw.WH_ID JOIN WAREHOUSE tw ON it.TO_WH_ID = tw.WH_ID JOIN EMPLOYEE e ON it.EMP_ID = e.EMP_ID LEFT JOIN COMMON_CODE cc ON i.UNIT_CODE = cc.CODE_ID AND cc.CODE_TYPE = 'UNIT_CODE'
AND (it.TRANSFER_NO LIKE '%' || #{keyword} || '%' OR i.ITEM_NAME LIKE '%' || #{keyword} || '%')
) WHERE rnum BETWEEN #{offset} + 1 AND #{offset} + #{size}

SELECT inv.ITEM_ID as itemId, i.ITEM_CODE as itemCode, i.ITEM_NAME as itemName, cc.CODE as itemUnit, inv.CURRENT_QTY as currentStock, inv.EXPECTED_QTY as expectedStock, inv.ALLOCATED_QTY as allocatedStock, (inv.CURRENT_QTY + inv.EXPECTED_QTY - inv.ALLOCATED_QTY) as availableStock FROM INVENTORY inv JOIN ITEM i ON inv.ITEM_ID = i.ITEM_ID LEFT JOIN COMMON_CODE cc ON i.UNIT_CODE = cc.CODE_ID AND cc.CODE_TYPE = 'UNIT_CODE' WHERE inv.WH_ID = #{whId}
AND (i.ITEM_CODE LIKE '%' || #{keyword} || '%' OR i.ITEM_NAME LIKE '%' || #{keyword} || '%')
AND (inv.CURRENT_QTY + inv.EXPECTED_QTY - inv.ALLOCATED_QTY) > 0 ORDER BY i.ITEM_NAME

SELECT (CURRENT_QTY + EXPECTED_QTY - ALLOCATED_QTY) as availableStock
FROM INVENTORY
WHERE ITEM_ID = #{itemId} AND WH_ID = #{whId}
